function concept(slug: string, text: Copy, locale: Locale) {
  if (slug.includes("-vat-") || slug.includes("-gst-")) return text.vat;
  if (slug.includes("income-tax") || slug.includes("irpf") || slug.includes("irrf")) return text.tax;
  if (slug.includes("gross-net-salary")) return text.salary;
  if (slug.includes("overtime")) return text.overtime;
  if (slug.includes("severance")) return text.severance;
  if (slug.includes("vacation-pay") || slug.includes("holiday-allowance")) return text.allowance;
  if (slug.includes("30-percent-ruling")) return locale === "nl" ? "30%-regeling" : `30% ${text.ruling}`;
  if (slug.includes("social-insurance") || slug.includes("labor-insurance") || slug.includes("inss")) return text.insurance;
  if (slug.includes("fgts")) return "FGTS";
  if (slug.includes("thirteenth-salary")) return locale === "pt-br" ? "13º salário" : locale === "es" ? "salario de 13.º mes" : "13th salary";
  if (slug.includes("-sip-")) return `SIP ${text.investment}`;
  if (slug.includes("-ppf-")) return `PPF ${text.investment}`;
  if (slug.includes("-nps-")) return `NPS ${text.investment}`;
  return text.investment;
}

