function modelFormula(slug: string, fields: Record<string, { label: string }>, source: (typeof countryRates)[string] | undefined, text: Copy): string {
  const field = (name: string) => fields[name]?.label ?? name;
  if (slug.endsWith("-vat-calculator") || slug.endsWith("-gst-calculator")) return `r = ${field("rate")} ÷ 100; ${text.resultTaxBase} × r = ${text.resultTax}; ${text.resultTaxBase} + ${text.resultTax} = ${text.resultTotal}; ${text.resultTotal} ÷ (1 + r) = ${text.resultTaxBase}.`;
  if (slug.endsWith("-overtime-pay-calculator")) return `${text.resultBasePay} = ${field("salary")} × ${field("hours")}; ${text.resultPremium} = ${text.resultBasePay} × (${field("multiplier")} − 1); ${text.resultAllowance} = ${text.resultBasePay} × ${field("multiplier")}.`;
  if (slug.endsWith("-vacation-pay-calculator") || slug.endsWith("-holiday-allowance-calculator")) return `${text.resultAllowance} = ${field("salary")} × ${field("rate")} ÷ 100.`;
  if (slug.endsWith("-severance-pay-calculator")) return `${text.resultBasePay} = ${field("salary")} × 12 ÷ 365; ${text.resultSeverance} = (${field("salary")} × 12 ÷ 365) × ${field("daysPerYear")} × ${field("years")}.`;
  if (slug.endsWith("-sip-calculator") || slug.endsWith("-ppf-calculator") || slug.endsWith("-nps-calculator")) return `m = ${field("years")} × 12; r = ${field("rate")} ÷ 12; ${text.resultInvested} = ${field("monthlyDeposit")} × m; ${text.resultBalance} = deposit × (((1 + r)^m − 1) ÷ r) × (1 + r); ${text.resultGains} = ${text.resultBalance} − ${text.resultInvested}.`;
  if (slug.endsWith("-30-percent-ruling-calculator")) return `r = min(${field("rate")}, 30%); ${text.resultExempt} = min(${field("salary")} × r, €78,600); ${text.resultTaxable} = ${field("salary")} − ${text.resultExempt}.`;
  if (slug.endsWith("-fgts-calculator")) return `${text.resultFund} = ${field("salary")} × 8%; ${text.resultAnnualFund} = ${text.resultFund} × 12.`;
  if (slug.endsWith("-thirteenth-salary-calculator")) return `${text.resultAllowance} = ${field("salary")} × ${field("months")} ÷ 12.`;
  if (slug.endsWith("-inss-calculator") || slug.endsWith("-irrf-calculator")) return slug.endsWith("-irrf-calculator") ? `${text.resultTax} = IRRF(${field("salary")} − INSS(${field("salary")})).` : `${text.resultContrib} = INSS(${field("salary")}).`;
  if (slug.endsWith("-social-insurance-calculator") || slug.endsWith("-labor-insurance-calculator")) return `${text.resultContrib} = ${field("contributionBase")} × ${field("rate")} ÷ 100.`;
  if (slug.endsWith("-paycheck-calculator") || slug.endsWith("-gross-net-salary-calculator") || slug.endsWith("-salary-tax-calculator")) return `${text.resultNet} = ${field("salary")} − ${text.resultTax} − ${text.resultContrib}; ${text.resultMonthlyNet} = ${text.resultNet} ÷ 12.`;
  if (slug.endsWith("-401k-calculator") || slug.endsWith("-roth-ira-calculator") || slug.endsWith("-rrsp-calculator") || slug.endsWith("-pension-calculator") || slug.endsWith("-superannuation-calculator") || slug.endsWith("-kiwisaver-calculator")) return `${text.resultBalance} = FV(${field("annualContribution")}, ${field("employerRate")}, ${field("rate")}, ${field("years")}); ${text.resultGains} = ${text.resultBalance} − ${text.resultInvested}.`;
  if (slug.endsWith("-capital-gains-tax-calculator")) return `${text.resultTaxBase} = max(0, ${field("salePrice")} − ${field("costBasis")}); ${text.resultTax} = F(${text.resultTaxBase}, ${field("term")}, ${field("filingStatus")}).`;
  if (slug.endsWith("-stamp-duty-calculator")) return `${text.resultAllowance} = F(${field("propertyValue")}, ${field("buyer")}).`;
  if (slug.endsWith("-cpf-calculator") || slug.endsWith("-mpf-calculator") || slug.endsWith("-epf-calculator") || slug.endsWith("-socso-calculator") || slug.endsWith("-sss-calculator") || slug.endsWith("-philhealth-calculator") || slug.endsWith("-pagibig-calculator") || slug.endsWith("-cpp-ei-calculator")) return `${text.resultContrib} = F(${field("salary")}${fields.age ? `, ${field("age")}` : ""}).`;
  if (slug.endsWith("-gratuity-calculator") || slug.endsWith("-end-of-service-calculator")) return `${text.resultSeverance} = F(${field("salary")}, ${field("years")}, ${field("months")}).`;
  if (slug.endsWith("-corporate-tax-calculator")) return source?.annualTaxBrackets ? `${text.resultTax} = Σ(${field("income")} bracket slice × bracket rate).` : `${text.resultTax} = ${field("income")} × ${field("rate")} ÷ 100.`;
  if (slug.endsWith("-sales-tax-calculator") || slug.endsWith("-sst-calculator")) return `${text.resultTax} = ${field("amount")} × ${field("rate")} ÷ 100; ${text.resultTotal} = ${field("amount")} + ${text.resultTax}.`;
  if (slug.endsWith("-national-insurance-calculator")) return `${text.resultContrib} = F(${field("salary")}, ${field("frequency")}).`;
  if (slug.endsWith("-freelancer-tax-calculator")) return `${text.resultTaxBase} = max(0, ${field("income")} − ${field("expenses")}); ${text.resultTax} = ${text.resultTaxBase} × ${field("rate")} ÷ 100; ${text.resultContrib} = ${field("contributionBase")} × ${field("socialRate")} ÷ 100 × 12.`;
  if (slug.endsWith("-income-tax-calculator") || slug.endsWith("-irpf-calculator") || slug.endsWith("-personal-income-tax-calculator") || slug.endsWith("-individual-income-tax-calculator")) return source?.annualTaxBrackets ? `${text.resultTax} = Σ(income slice × bracket rate); ${text.resultAverageRate} = ${text.resultTax} ÷ ${field("income")}.` : `${text.resultTax} = ${field("income")} × ${field("rate")} ÷ 100.`;
  if (slug.endsWith("-gross-net-salary-calculator")) return `${text.resultNet} = ${field("salary")} − ${text.resultTax} − ${text.resultContrib}; ${text.resultMonthlyNet} = ${text.resultNet} ÷ 12.`;
  return text.formula;
}

export function phaseFiveLocaleContent(locale: Locale): Partial<Record<(typeof countrySpecificCalculatorSlugs)[number], LocalizedCalculatorContent>> {
  const text = copy[locale];
  const localized = Object.fromEntries(countrySpecificCalculatorSlugs.map((slug) => {
    const page = getCalculatorPage(slug)!;
    const code = countryCodeFromSlug(slug);
    const localizedCountry = countryNames[code]![locale];
    const name = `${localizedCountry} ${concept(slug, text, locale)}`;
    const source = countryRates[code]!;
    const fields = Object.fromEntries(page.fields.map((field) => {
      const label = field.name === "amount" ? text.fieldAmount : field.name === "salary" ? text.fieldSalary : field.name === "income" ? text.fieldIncome : field.name === "frequency" ? text.fieldFrequency : field.name === "rate" || field.name === "socialRate" || field.name === "taxRate" ? text.fieldRate : field.name === "hours" ? text.fieldHours : field.name === "multiplier" ? text.fieldMultiplier : field.name === "direction" ? text.fieldDirection : field.name === "years" ? text.fieldYears : field.name === "daysPerYear" ? text.fieldDays : field.name === "months" ? text.fieldMonths : field.name === "monthlyDeposit" ? text.fieldAmount : text.fieldBase;
      return [field.name, { label, ...(field.unit ? { unit: field.unit } : {}) }];
    }));
    const dayWord: Record<Locale, string> = { ko: "일", en: "days", ja: "日", zh: "天", es: "días", "pt-br": "dias", de: "Tage", fr: "jours", vi: "ngày", id: "hari", th: "วัน", "zh-tw": "天", it: "giorni", nl: "dagen", hi: "दिन" };
    const options = Object.fromEntries(page.fields.filter((field) => field.options).map((field) => [field.name, Object.fromEntries(field.options!.map((option) => [option.value, field.name === "daysPerYear" ? `${option.value} ${dayWord[locale]}` : option.value === "annual" ? text.optionAnnual : option.value === "monthly" ? text.optionMonthly : option.value === "exclusive" ? text.optionAdd : option.value === "inclusive" ? text.optionExtract : option.label]))]));
    return [slug, { name, shortName: name, title: `${name} (${source.policyYear})`, description: `${name}. ${policyStatements[locale]} ${text.warning}`, keywords: [name, `${localizedCountry} ${concept(slug, text, locale)}`], howTo: `${text.howTo} ${policyStatements[locale]} ${text.warning}`, formula: modelFormula(slug, fields, source, text), example: { question: text.example, answer: text.answer }, faqs: [{ question: text.faq, answer: text.faqAnswer }, { question: locale === "ko" ? "언어를 바꾸면 계산 국가도 바뀌나요?" : locale === "ja" ? "言語を変更すると計算対象国も変わりますか？" : locale === "zh" ? "更改语言会改变计算国家吗？" : locale === "es" ? "¿Cambiar el idioma cambia el país del cálculo?" : locale === "fr" ? "La langue modifie-t-elle le pays du calcul ?" : locale === "de" ? "Ändert ein Sprachwechsel das Berechnungsland?" : locale === "nl" ? "Verandert de taal het rekenland?" : locale === "it" ? "La lingua cambia il Paese di calcolo?" : locale === "pt-br" ? "Mudar o idioma altera o país do cálculo?" : locale === "vi" ? "Đổi ngôn ngữ có đổi quốc gia tính toán không?" : locale === "id" ? "Apakah bahasa mengubah negara perhitungan?" : locale === "th" ? "เปลี่ยนภาษาแล้วประเทศที่คำนวณเปลี่ยนหรือไม่" : locale === "zh-tw" ? "切換語言會改變計算國家嗎？" : locale === "hi" ? "क्या भाषा बदलने से गणना का देश बदलता है?" : "Does changing language change the calculation country?", answer: policyStatements[locale] }], related: page.relatedCalculatorIds as LocalizedCalculatorContent["related"], fields, options, resultLabels: resultLabels(text), validation: text.warning, resultNote: text.warning } satisfies LocalizedCalculatorContent];
  })) as Partial<Record<(typeof countrySpecificCalculatorSlugs)[number], LocalizedCalculatorContent>>;
  const labels = contentPatterns[locale];
  return Object.fromEntries(countrySpecificCalculatorSlugs.map((slug) => {
    const page = getCalculatorPage(slug)!;
    const content = localized[slug]!;
    const fieldNames = page.fields.map((field) => content.fields[field.name]?.label ?? field.label).join(", ");
    const localizedFields = Object.fromEntries(Object.entries(content.fields).map(([key, value]) => [key, value.label]));
    const example = calculatorExample(page, locale, localizedFields, content.resultLabels);
    return [slug, {
      ...content,
      description: example ? `${purposeSentence(locale, page.fields.slice(0, 3).map((field) => content.fields[field.name]?.label ?? field.label), [example.primaryLabel])} ${content.description}` : content.description,
      howTo: `${content.name}: ${labels.inputs}: ${fieldNames}. ${content.howTo}`,
      example: example ? { question: `${content.name} — ${labels.exampleInput}: ${example.input}`, answer: `${labels.exampleResult}: ${example.result}. ${content.resultNote}` } : content.example,
      faqs: [{ question: `${content.name}: ${labels.inputQuestion}`, answer: `${labels.inputAnswer} ${fieldNames}. ${content.resultNote}` }, content.faqs[0]!],
    } satisfies LocalizedCalculatorContent];
  })) as Partial<Record<(typeof countrySpecificCalculatorSlugs)[number], LocalizedCalculatorContent>>;
}
